/// The `start` / `middle` / `end` / `2` connectors of `kind`
/// (`type * 3 + width`) in locale `loc`.
pub(crate) fn patterns(loc: u16, kind: u16) -> [&'static str; 4] {
    let at = ROW_IDX
        .get(loc as usize * 9 + kind as usize)
        .map_or(0, |r| *r as usize * 4);
    core::array::from_fn(|i| str_at(ROWS.get(at + i).copied().unwrap_or(0)))
}

/// The interned pattern with id `id`. Arena boundaries always fall on
/// char boundaries — it is whole strings concatenated — but `get` is
/// used anyway so a corrupt table cannot panic.
fn str_at(id: u16) -> &'static str {
    let i = id as usize;
    match (STRINGS.get(i), STRINGS.get(i + 1)) {
        (Some(a), Some(b)) => ARENA.get(*a as usize..*b as usize).unwrap_or(""),
        _ => "",
    }
}

